CREATE POLICY "student_photos_owner_read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'student-photos' AND name = (auth.uid()::text || '/avatar'));
CREATE POLICY "student_photos_owner_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'student-photos' AND name = (auth.uid()::text || '/avatar'));
CREATE POLICY "student_photos_owner_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'student-photos' AND name = (auth.uid()::text || '/avatar')) WITH CHECK (bucket_id = 'student-photos' AND name = (auth.uid()::text || '/avatar'));